class Solution {
public:
    vector<int> findCommonElements(vector<int>& nums1, vector<int>& nums2) {
        int a1 = 0, a2 = 0;
        for (int x : nums1)
            for (int y : nums2) if (x == y) { a1++; break; }
        for (int x : nums2)
            for (int y : nums1) if (x == y) { a2++; break; }
        return {a1, a2};
    }
};

