class Solution {
    public int[] findCommonElements(int[] nums1, int[] nums2) {
        Set<Integer> s1 = new HashSet<>(), s2 = new HashSet<>();
        for (int x : nums1) s1.add(x);
        for (int x : nums2) s2.add(x);
        int a1 = 0, a2 = 0;
        for (int x : nums1) if (s2.contains(x)) a1++;
        for (int x : nums2) if (s1.contains(x)) a2++;
        return new int[]{a1, a2};
    }
}

